INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 110501, 10021, "2030/12/17 14:59:59", "あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", 4, "カオリ（サマー）", 24, 0.0, 0.0, 24015, 1, 0.0, 4);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 110501, 10021, "2030/12/17 14:59:59", "今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", 1, "カオリ（サマー）", 24, 4.0, 0.0, 24016, 2, 0.0, 4);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 110501, 10021, "2030/12/17 14:59:59", "マジムンだらけで目が回るさ～！\nふらふらさ～！", 4, "カオリ（サマー）", 24, 0.0, 0.0, 24017, 3, 0.0, 4);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 110501, 10021, "2030/12/17 14:59:59", "なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", 2, "カオリ（サマー）", 24, 5.2, 0.0, 24018, 4, 0.0, 1);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 110501, 10021, "2030/12/17 14:59:59", "恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", 6, "カオリ（サマー）", 24, 4.2, 0.0, 24019, 5, 0.0, 5);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 110501, 10021, "2030/12/17 14:59:59", "絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", 2, "カオリ（サマー）", 24, 0.0, 0.0, 24020, 6, 0.0, 2);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 110501, 10021, "2030/12/17 14:59:59", "何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", 6, "カオリ（サマー）", 24, 6.4, 0.0, 24021, 7, 0.0, 1);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 110501, 10021, "2030/12/17 14:59:59", "ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", 2, "カオリ（サマー）", 24, 0.0, 0.0, 24022, 8, 0.0, 2);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 110501, 10021, "2030/12/17 14:59:59", "あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", 3, "カオリ（サマー）", 24, 10.08, 0.0, 24023, 9, 0.0, 6);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 110501, 10021, "2030/12/17 14:59:59", "まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", 2, "カオリ（サマー）", 24, 5.0, 0.0, 24024, 10, 0.0, 1);
INSERT INTO `v1_7848f82e2281d11ca0834ed133734a84fbb81ccb0a06c0f257895346375cbb6e` VALUES ("2019/07/31 12:00:00", 110501, 10021, "2030/12/17 14:59:59", "私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", 2, "カオリ（サマー）", 24, 0.0, 0.0, 24025, 11, 0.0, 2);
